mapper.select:
SELECT id, artifact_name, artifact_version, app_name, user_id, session_id, object_key,
       file_name, mime_type, size_bytes, created_at, expires_at
FROM attachment_objects
WHERE artifact_name = #{artifactName}
  AND app_name = #{appName}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND expires_at > CURRENT_TIMESTAMP

  AND artifact_version = #{artifactVersion}

ORDER BY artifact_version DESC
LIMIT 1

SELECT DISTINCT artifact_name
FROM attachment_objects
WHERE app_name = #{appName}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
  AND artifact_name IS NOT NULL
  AND expires_at > CURRENT_TIMESTAMP
ORDER BY artifact_name ASC

SELECT id, artifact_name, artifact_version, app_name, user_id, session_id, object_key,
       file_name, mime_type, size_bytes, created_at, expires_at
FROM attachment_objects
WHERE artifact_name = #{artifactName}
  AND app_name = #{appName}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY artifact_version ASC

SELECT artifact_version
FROM attachment_objects
WHERE artifact_name = #{artifactName}
  AND app_name = #{appName}
  AND user_id = #{userId}
  AND session_id = #{sessionId}
ORDER BY artifact_version ASC

mapper.delete:
DELETE FROM attachment_objects
WHERE artifact_name = #{artifactName}
  AND app_name = #{appName}
  AND user_id = #{userId}
  AND session_id = #{sessionId}

mapper.select:
