SELECT id, artifact_name, artifact_version, app_name, user_id, session_id, object_key,
       file_name, mime_type, size_bytes, created_at, expires_at
FROM attachment_objects
WHERE expires_at <= #{now}
ORDER BY expires_at ASC, id ASC
LIMIT #{limit}
